attributes.screen_custom_css:
[selector='Desktop']{
  /*background-color: #F6F8FC;*/
  min-height: 800px;
  max-height: 900px;
}
[selector='Mobile']{
  background-color: #F6F8FC;
  padding-left: 0px;
  padding-right:0px ;
}
[selector='Header1']{
  background-color: #237DB3;
  padding:20px 30px 0px 30px;
}
[selector='Header2']{
  background-color: #237DB3;
  padding:10px 0px 0px 10px;
}
[selector='Header2'] .col-sm-2{
  padding-right: 0px !important;
  width: 40%;
}
[selector='Header2'] .col-sm-10{
  padding-right: 0px !important;
  width: 80%;
}
[selector='Header2'] .row{
  flex-wrap: nowrap !important;
}

[selector='Header1'] img{
  text-align: right !important;
  float: right;
}
.TitleText{
  color:#FFFFFF;
  font-size: 20px;
  font-weight: 600;
  font-family: Arial, Helvetica, sans-serif;
  line-height: 28px;
}
.TitleTextMobile{
      color: #FFFFFF;
    font-size: 17px;
    font-weight: 500;
    font-family: Arial, Helvetica, sans-serif;
    margin-bottom: 0px;
    margin-top: -5px;
}
.Text{
  color:#FFFFFF;
  font-size: 18px;
  font-weight: 400;
  font-family: Arial, Helvetica, sans-serif;
  line-height: 24px;
}
.TextMobile{
  color: #FFFFFF;
    font-size: 14px;
    font-weight: 400;
    font-family: Arial, Helvetica, sans-serif;
    margin-bottom: 0px;
    margin-top: -5px;
}
.TitleTextBlack{
  color:#39404A;
  font-size: 22px;
  font-weight: 600;
  font-family: Arial, Helvetica, sans-serif;
  line-height: 20px;
}
.TitleTextBlackMobile{
  color:#39404A;
  font-size: 17px;
  font-weight: 600;
  font-family: Arial, Helvetica, sans-serif;
  line-height: 20px;
}
.TextData{
  color:#5F6367;
  font-size: 18px;
  font-weight: 700;
  font-family: Arial, Helvetica, sans-serif;
  line-height: 21px;
}
.TextDataText{
  color:#5F6367;
  font-size: 16px;
  font-weight: 400;
  font-family: Arial, Helvetica, sans-serif;
  line-height: 21px;
  text-align: right;
}
[selector='BgContainer']{
  min-height: 700px;
}
[selector='BgGrid']{
  background-color: #F6F8FC;
  padding: 50px 30px 30px 30px;
  min-height: 700px;
}
[selector='BgGridWhite']{
  background-color: #FFFFFF;
  padding: 50px 30px 30px 30px;
  min-height: 700px;
}
[selector='BgGridWhiteMobile']{
  background-color: #FFFFFF;
  padding: 10px 5px 0px 10px;
  border-bottom: 1px solid #DDD;
}
[selector='BgGridWhiteMobile'] .row{
  flex-wrap: nowrap !important;
}
[selector='BgGridWhiteMobile'] .col-sm-9{
  width: 80%;
}
[selector='BgGridWhiteMobile'] .col-sm-3{
  width: 20%;
}
[selector='ContainerStyle'] .form-control {
    color: #20242A;
    border: 1px solid #D7DDE5;
    border-radius: 8px;
    box-shadow: 0px 1px 4px 0px rgb(218 218 218 / 75%);
    padding: 20px 15px;
}
[selector='ContainerStyle'] .form-group label {
    margin-bottom: 5px;
    color: #20242A;
    font-size: 14px;
    font-weight: 400;
    line-height: 20px;
}
[selector='ContainerStyleMobile'] .form-control {
    color: #20242A;
    border: 1px solid #D7DDE5;
    border-radius: 8px;
    box-shadow: 0px 1px 4px 0px rgb(218 218 218 / 75%);
    font-size: 12px;
}
[selector='ContainerStyleMobile'] .form-group label {
    margin-bottom: 5px;
    color: #20242A;
    font-size: 12px;
    font-weight: 400;
    line-height: 20px;
}
[selector='BtnStyle'] .btn-primary {
    background-color: #20242A;
    border:1px solid #20242A;
    border-radius: 8px 8px 8px 8px;
    color:#FFFFFF;
    font-size: 14px;
    font-weight: 500;
    line-height: 20px;
    width: 100%;
    text-align: center;
    padding: 12px 5px;
}
[selector='BtnStyle'] .btn-primary:hover {
    background-color: #010101;
    border:1px solid #010101;
    color:#FFFFFF;
}
[selector='BtnStyle'] .btn-danger {
    background-color: #FFFFFF;
    border:1px solid #D7DDE5;
    border-radius: 8px 8px 8px 8px;
    color:#20242A;
    font-size: 14px;
    font-weight: 500;
    line-height: 20px;
    width: 100%;
    text-align: center;
    padding: 12px 5px;
    text-transform: capitalize;
}
[selector='BtnStyle'] .btn-danger::before {
  content: "";
  display: inline-block;
  background-image: url(https://plg-winter.dev.cloud.processmaker.net/public-files/Shape.png);
  background-repeat: no-repeat;
  width: 20px;
  height: 20px;
  margin-bottom: -8px;
}

[selector='BtnStyle'] .btn-danger:hover {
    background-color: #D7DDE5;
    border:1px solid #D7DDE5;
    color:#20242A;
}

[selector='BtnStyleMobile']{
  /*position: fixed;
  bottom: 0;*/
}
[selector='BtnStyleMobile'] .btn-primary {
    background-color: #20242A;
    border:1px solid #20242A;
    border-radius: 8px 8px 8px 8px;
    color:#FFFFFF;
    font-size: 12px;
    font-weight: 500;
    line-height: 20px;
    width: 100%;
    text-align: center;
}
[selector='BtnStyleMobile'] .btn-danger {
    background-color: #FFFFFF;
    border:1px solid #D7DDE5;
    border-radius: 8px 8px 8px 8px;
    color:#20242A;
    font-size: 12px;
    font-weight: 500;
    line-height: 20px;
    width: 100%;
    text-align: center;
}
[selector='ContainerMobile'] {
    padding: 10px;
}
[selector='BorderBottom'] {
    margin-top: 20px;
}
[selector='NumbersContainer'] .form-group label{
    display: none;
}
[selector='NumbersContainer'] .btn-danger{
    text-align: right;
    float: right;
    margin-top: 2px;
}
[selector='NumbersContainer'] .btn-success{
    text-align: left;
    float: left;
    margin-top: 2px;
}
[selector='NumbersContainer'] .col-sm-8{
    padding-left: 5px !important;
    padding-right: 5px !important;
}
[selector='NumbersContainer'] .col-sm-2{
    padding-left: 0px !important;
    padding-right: 0px !important;
}

/***NumbersContainerMobile***/
[selector='NumbersContainerMobile'] .row{
  flex-wrap: nowrap !important;
}
[selector='NumbersContainerMobile'] .form-group label{
    display: none;
}
[selector='NumbersContainerMobile'] .btn-danger{
    text-align: right;
    float: right;
    margin-top: 2px;
}
[selector='NumbersContainerMobile'] .btn-success{
    text-align: left;
    float: left;
    margin-top: 2px;
}
[selector='NumbersContainerMobile'] .col-sm-8{
    padding-left: 5px !important;
    padding-right: 5px !important;
    min-width: 60%;
}
[selector='NumbersContainerMobile'] .col-sm-2{
    padding-left: 5px !important;
    padding-right: 5px !important;
    min-width: 15%;
}
